  WHERE d.enabled IS TRUE
    AND d.schedule_cron IS NOT NULL;

  RETURN v_body;
END;
$$;

-- Interval jobs for scheduler-entrypoint sleep loops: "job_name\tseconds" per line.
CREATE OR REPLACE FUNCTION api.scheduler_interval_jobs()
RETURNS text
LANGUAGE plpgsql
