    string_agg(d.job_name || E'\t' || d.interval_seconds::text, E'\n' ORDER BY d.job_name),
    ''
  )
  INTO v_body
  FROM maintenance.job_definition AS d
  WHERE d.enabled IS TRUE
    AND d.interval_seconds IS NOT NULL;

  RETURN COALESCE(v_body, '');
END;
$$;

