CREATE OR REPLACE FUNCTION public.notify_poc_counter_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.label = 'poc_counter'
     AND (TG_OP = 'INSERT' OR OLD.value IS DISTINCT FROM NEW.value) THEN
    PERFORM pg_notify(
      'system_config_poc_counter',
      public.system_config_value_text(NEW.value)
    );
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER system_config_notify_poc_counter
  AFTER INSERT OR UPDATE OF value ON public.system_config
  FOR EACH ROW
  EXECUTE FUNCTION public.notify_poc_counter_change();

CREATE OR REPLACE FUNCTION api.poc_counter_tick()
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, api
AS $$
DECLARE
  v_label text := 'poc_counter';
  v_modified timestamptz;
  v_value text;
  v_action text;
  v_tz text := 'America/Chicago';
BEGIN
  IF NOT pg_try_advisory_xact_lock(901001, hashtext('poc_counter_tick')) THEN
    RETURN json_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'already_running'
    );
  END IF;

  PERFORM api.set_audit_actor('maintenance');

  SELECT s.modified_date, public.system_config_value_text(s.value)
  INTO v_modified, v_value
  FROM public.system_config AS s
  WHERE s.label = v_label
    AND s.active IS NOT FALSE
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'ok', false,
      'skipped', false,
      'error_message', 'poc_counter row not found'
    );
  END IF;

  IF date_trunc('hour', clock_timestamp() AT TIME ZONE v_tz)
       > date_trunc('hour', COALESCE(v_modified, '-infinity'::timestamptz) AT TIME ZONE v_tz)
  THEN
    UPDATE public.system_config
    SET
      value = to_jsonb(0),
      modified_by = 'maintenance',
      modified_date = CURRENT_TIMESTAMP
    WHERE label = v_label
      AND active IS NOT FALSE;

    v_action := 'reset';
    v_value := '0';
  ELSE
    UPDATE public.system_config
    SET
      value = to_jsonb(
        COALESCE(NULLIF(public.system_config_value_text(value), ''), '0')::int + 1
      ),
      modified_by = 'maintenance',
      modified_date = CURRENT_TIMESTAMP
    WHERE label = v_label
      AND active IS NOT FALSE
    RETURNING public.system_config_value_text(value) INTO v_value;

    v_action := 'increment';
  END IF;

  RETURN json_build_object(
    'ok', true,
    'skipped', false,
    'action', v_action,
    'value', v_value
  );
END;
$$;

CREATE OR REPLACE FUNCTION api.robot_riot_attendee_churn()
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, api, maintenance
AS $$
DECLARE
  v_event_id bigint;
  v_event_name text := 'Robot Riot 2026';
  v_attendee_count integer;
  v_remove integer;
  v_replaced integer := 0;
  v_available integer;
  v_until timestamptz;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(901001, hashtext('robot_riot_attendee_churn')) THEN
    RETURN json_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'already_running'
    );
  END IF;

  PERFORM api.set_audit_actor('maintenance');

  SELECT NULLIF(trim(public.system_config_value_text(s.value)), '')::timestamptz
  INTO v_until
  FROM public.system_config AS s
  WHERE s.label = 'robot_riot_attendee_churn_until'
    AND s.active IS NOT FALSE;

  IF v_until IS NULL OR v_now >= v_until THEN
    DELETE FROM maintenance.job_definition
    WHERE job_name = 'robot_riot_attendee_churn';

    UPDATE public.system_config
    SET
      value = NULL,
      modified_by = 'maintenance',
      modified_date = CURRENT_TIMESTAMP
    WHERE label = 'robot_riot_attendee_churn_until'
      AND active IS NOT FALSE
      AND value IS NOT NULL;

    RETURN json_build_object(
      'ok', true,
      'skipped', true,
      'reason', CASE WHEN v_until IS NULL THEN 'not_started' ELSE 'window_expired' END,
      'cleaned_up', true,
      'until', v_until
    );
  END IF;

  SELECT e.event_id
  INTO v_event_id
  FROM public."event" AS e
  WHERE e.event_group_code = 'ROBOT_RIOT'
    AND e.name = v_event_name
  ORDER BY e.event_id
  LIMIT 1;

  IF v_event_id IS NULL THEN
    RETURN json_build_object(
      'ok', false,
      'skipped', false,
      'error_message', format('Event not found: %s', v_event_name)
    );
  END IF;

  SELECT count(*)::integer
  INTO v_attendee_count
  FROM public.attendee AS a
  WHERE a.event_id = v_event_id;

  IF v_attendee_count = 0 THEN
    RETURN json_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'no_attendees',
      'event_id', v_event_id,
      'event_name', v_event_name,
      'until', v_until
    );
  END IF;

  v_remove := GREATEST(1, floor(v_attendee_count * 0.10)::integer);

  SELECT count(*)::integer
  INTO v_available
  FROM public."user" AS u
  WHERE u.active IS NOT FALSE
    AND NOT EXISTS (
      SELECT 1
      FROM public.attendee AS a
      WHERE a.event_id = v_event_id
        AND a.user_id = u.user_id
    );

  IF v_available = 0 THEN
    RETURN json_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'no_replacement_users',
      'event_id', v_event_id,
      'event_name', v_event_name,
      'attendee_count', v_attendee_count,
      'until', v_until
    );
  END IF;

  v_remove := LEAST(v_remove, v_available);

  WITH to_replace AS (
    SELECT s.attendee_id, row_number() OVER () AS rn
    FROM (
      SELECT a.attendee_id
      FROM public.attendee AS a
      WHERE a.event_id = v_event_id
      ORDER BY random()
      LIMIT v_remove
    ) AS s
  ),
  replacements AS (
    SELECT s.user_id, row_number() OVER () AS rn
    FROM (
      SELECT u.user_id
      FROM public."user" AS u
      WHERE u.active IS NOT FALSE
        AND NOT EXISTS (
          SELECT 1
          FROM public.attendee AS a
          WHERE a.event_id = v_event_id
            AND a.user_id = u.user_id
        )
      ORDER BY random()
      LIMIT v_remove
    ) AS s
  ),
  paired AS (
    SELECT t.attendee_id, r.user_id
    FROM to_replace AS t
    INNER JOIN replacements AS r ON r.rn = t.rn
  )
  UPDATE public.attendee AS a
  SET
    user_id = p.user_id,
    modified_by = 'maintenance',
    modified_date = CURRENT_TIMESTAMP
  FROM paired AS p
  WHERE a.attendee_id = p.attendee_id;

  GET DIAGNOSTICS v_replaced = ROW_COUNT;

  RETURN json_build_object(
    'ok', true,
    'skipped', false,
    'event_id', v_event_id,
    'event_name', v_event_name,
    'attendee_count', v_attendee_count,
    'requested_remove', GREATEST(1, floor(v_attendee_count * 0.10)::integer),
    'replaced', v_replaced,
    'until', v_until
  );
END;
$$;

CREATE OR REPLACE FUNCTION api.start_robot_riot_attendee_churn(p_duration_minutes integer DEFAULT 10)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, api, maintenance
AS $$
DECLARE
  v_user_id bigint;
  v_username text;
  v_minutes integer := COALESCE(p_duration_minutes, 10);
  v_until timestamptz;
  v_first json;
BEGIN
  v_user_id := api.current_user_id();

  IF v_user_id IS NULL THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'You are not signed in.'
    );
  END IF;

  IF NOT api.has_app_role('ADMIN') THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'Admin role required.'
    );
  END IF;

  IF v_minutes < 1 OR v_minutes > 60 THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'duration_minutes must be between 1 and 60.'
    );
  END IF;

  SELECT u.username
  INTO v_username
  FROM public."user" AS u
  WHERE u.user_id = v_user_id
    AND u.active IS NOT FALSE;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'Account not found.'
    );
  END IF;

  PERFORM api.set_audit_actor(v_username);

  v_until := date_trunc('second', clock_timestamp() + make_interval(mins => v_minutes));

  UPDATE public.system_config
  SET
    value = to_jsonb(v_until::text),
    modified_by = v_username,
    modified_date = CURRENT_TIMESTAMP
  WHERE label = 'robot_riot_attendee_churn_until'
    AND active IS NOT FALSE;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'robot_riot_attendee_churn_until config row not found.'
    );
  END IF;

  INSERT INTO maintenance.job_definition (
    job_name,
    rpc_schema,
    rpc_name,
    schedule_cron,
    interval_seconds,
    is_enabled,
    stale_after_interval,
    description,
    created_by
  )
  VALUES (
    'robot_riot_attendee_churn',
    'api',
    'robot_riot_attendee_churn',
    NULL,
    60,
    true,
    INTERVAL '3 minutes',
    format(
      'Timed Robot Riot 2026 attendee rotation (every 60s until %s).',
      v_until
    ),
    v_username
  )
  ON CONFLICT (job_name) DO UPDATE
  SET
    rpc_schema = EXCLUDED.rpc_schema,
    rpc_name = EXCLUDED.rpc_name,
    schedule_cron = EXCLUDED.schedule_cron,
    interval_seconds = EXCLUDED.interval_seconds,
    is_enabled = true,
    stale_after_interval = EXCLUDED.stale_after_interval,
    description = EXCLUDED.description,
    modified_date = CURRENT_TIMESTAMP,
    modified_by = v_username;

  v_first := api.robot_riot_attendee_churn();

  RETURN json_build_object(
    'ok', true,
    'message', format(
      'Robot Riot 2026 attendee rotation started for %s minute(s).',
      v_minutes
    ),
    'duration_minutes', v_minutes,
    'until', v_until,
    'first_run', v_first
  );
END;
$$;

NOTIFY pgrst, 'reload schema';$sqlbody$,
  $sort$126_system_config_value_jsonb.sql$sort$,
  'c-agent'
);

INSERT INTO maintenance.schema_migration_catalog (
  filename, script_number, details, probe, sql_body, sort_key, created_by
) VALUES (
  $fn$127_app_role_rename_event_director_manager.sql$fn$,
  $num$127$num$,
  $details$Roles are still EVENT_COORDINATOR and BALLROOM_COORDINATOR.$details$,
  $probe$EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'user_app_role_role_code_check' AND pg_get_constraintdef(pg_constraint.oid) LIKE '%EVENT_DIRECTOR%')$probe$,
  $sqlbody$-- Rename EVENT_COORDINATOR -> EVENT_DIRECTOR; BALLROOM_COORDINATOR -> EVENT_MANAGER.
-- Run: psql -U postgres -d event_system_pro -f database/migrations/127_app_role_rename_event_director_manager.sql


ALTER TABLE public.user_app_role
  DROP CONSTRAINT IF EXISTS user_app_role_role_code_check;

-- Avoid PK conflicts when a user already has the target role.
DELETE FROM public.user_app_role old
WHERE old.role_code = 'EVENT_COORDINATOR'
  AND EXISTS (
    SELECT 1
    FROM public.user_app_role newer
    WHERE newer.user_id = old.user_id
      AND newer.role_code = 'EVENT_DIRECTOR'
  );

DELETE FROM public.user_app_role old
WHERE old.role_code = 'BALLROOM_COORDINATOR'
  AND EXISTS (
    SELECT 1
    FROM public.user_app_role newer
    WHERE newer.user_id = old.user_id
      AND newer.role_code = 'EVENT_MANAGER'
  );

UPDATE public.user_app_role
SET role_code = 'EVENT_DIRECTOR'
WHERE role_code = 'EVENT_COORDINATOR';

UPDATE public.user_app_role
SET role_code = 'EVENT_MANAGER'
WHERE role_code = 'BALLROOM_COORDINATOR';

UPDATE public."user"
SET volunteer_json = replace(volunteer_json::text, 'EVENT_COORDINATOR', 'EVENT_DIRECTOR')::json
WHERE volunteer_json IS NOT NULL
  AND volunteer_json::text LIKE '%EVENT_COORDINATOR%';

UPDATE public."user"
SET volunteer_json = replace(volunteer_json::text, 'BALLROOM_COORDINATOR', 'EVENT_MANAGER')::json
WHERE volunteer_json IS NOT NULL
  AND volunteer_json::text LIKE '%BALLROOM_COORDINATOR%';

ALTER TABLE public.user_app_role
  ADD CONSTRAINT user_app_role_role_code_check
  CHECK (role_code IN (
    'ADMIN',
    'STAFF',
    'JUDGE',
    'HEAD_JUDGE',
    'REGISTRATION',
    'FLOOR_PARENT',
    'EVENT_MANAGER',
    'DJ',
    'EVENT_DIRECTOR',
    'COMPETITOR'
  ));

NOTIFY pgrst, 'reload schema';$sqlbody$,
  $sort$127_app_role_rename_event_director_manager.sql$sort$,
  'c-agent'
);

INSERT INTO maintenance.schema_migration_catalog (
  filename, script_number, details, probe, sql_body, sort_key, created_by
) VALUES (
  $fn$128_admin_update_user.sql$fn$,
  $num$128$num$,
  $details$api.admin_update_user() is missing.$details$,
  $probe$to_regprocedure('api.admin_update_user(bigint, text, text, text, text)') IS NOT NULL OR to_regprocedure('api.admin_update_user(bigint, text, text, text, text, json, text)') IS NOT NULL$probe$,
  $sqlbody$-- Admin-only RPC to update a user's first/last name, username, and optional password.
-- Run: psql -U postgres -d event_system_pro -f database/migrations/128_admin_update_user.sql


CREATE OR REPLACE FUNCTION api.admin_update_user(
  p_user_id bigint,
  p_first_name text,
  p_last_name text,
  p_username text,
  p_new_password text DEFAULT NULL
)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, api
AS $$
DECLARE
  v_actor_user_id bigint;
  v_actor_username text;
  v_target public."user"%ROWTYPE;
  v_username text;
  v_first text;
  v_last text;
  v_display text;
  v_password text;
  v_name_json jsonb;
BEGIN
  v_actor_user_id := api.current_user_id();

  IF v_actor_user_id IS NULL THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'You are not signed in.'
    );
  END IF;

  IF NOT api.has_app_role('ADMIN') THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'Admin role required.'
    );
  END IF;

  IF p_user_id IS NULL THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'User id is required.'
    );
  END IF;

  v_username := trim(COALESCE(p_username, ''));
  v_first := trim(COALESCE(p_first_name, ''));
  v_last := trim(COALESCE(p_last_name, ''));
  v_password := NULLIF(trim(COALESCE(p_new_password, '')), '');

  IF v_username = '' THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'Username is required.'
    );
  END IF;

  IF length(v_username) > 64 THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'Username must be 64 characters or fewer.'
    );
  END IF;

  IF v_password IS NOT NULL AND length(v_password) < 8 THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'New password must be at least 8 characters.'
    );
  END IF;

  SELECT u.username
  INTO v_actor_username
  FROM public."user" u
  WHERE u.user_id = v_actor_user_id
    AND u.active IS NOT FALSE;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'Account not found.'
    );
  END IF;

  SELECT *
  INTO v_target
  FROM public."user" u
  WHERE u.user_id = p_user_id
    AND u.active IS NOT FALSE;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'User not found.'
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public."user" u
    WHERE lower(u.username) = lower(v_username)
      AND u.user_id <> p_user_id
  ) THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'That username is already taken.'
    );
  END IF;

  v_display := NULLIF(trim(concat_ws(' ', NULLIF(v_first, ''), NULLIF(v_last, ''))), '');
  v_name_json := COALESCE(v_target.name_json::jsonb, '{}'::jsonb);
  v_name_json := jsonb_set(v_name_json, '{first}', to_jsonb(NULLIF(v_first, '')), true);
  v_name_json := jsonb_set(v_name_json, '{last}', to_jsonb(NULLIF(v_last, '')), true);
  v_name_json := jsonb_set(v_name_json, '{display}', to_jsonb(v_display), true);

  PERFORM api.set_audit_actor(v_actor_username);

  IF v_password IS NOT NULL THEN
    UPDATE public."user"
    SET
      username = v_username,
      name_json = v_name_json::json,
      password_encrypted = crypt(v_password, gen_salt('bf')),
      modified_date = CURRENT_TIMESTAMP,
      modified_by = v_actor_username
    WHERE user_id = p_user_id;
  ELSE
    UPDATE public."user"
    SET
      username = v_username,
      name_json = v_name_json::json,
      modified_date = CURRENT_TIMESTAMP,
      modified_by = v_actor_username
    WHERE user_id = p_user_id;
  END IF;

  RETURN json_build_object(
    'ok', true,
    'message', 'User updated.',
    'user_id', p_user_id,
    'username', v_username
  );
END;
$$;

