  filename, script_number, details, probe, sql_body, sort_key, created_by
) VALUES (
  $fn$131_set_scheduled_task_interval.sql$fn$,
  $num$131$num$,
  $details$Change a task interval is missing.$details$,
  $probe$to_regprocedure('api.set_scheduled_task_interval(text, integer, text)') IS NOT NULL$probe$,
  $sqlbody$-- Admin RPC to update a maintenance job to an interval_seconds schedule (clears schedule_cron).
-- Run: psql -U postgres -d event_system_pro -f database/migrations/131_set_scheduled_task_interval.sql


CREATE OR REPLACE FUNCTION api.set_scheduled_task_interval(
  p_job_name text,
  p_interval_seconds integer,
  p_stale_after_interval text DEFAULT NULL
)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, api, maintenance
AS $$
DECLARE
  v_user_id bigint;
  v_username text;
  v_job_name text := lower(trim(COALESCE(p_job_name, '')));
  v_interval integer := p_interval_seconds;
  v_stale_text text := NULLIF(btrim(COALESCE(p_stale_after_interval, '')), '');
  v_stale interval;
BEGIN
  v_user_id := api.current_user_id();

  IF v_user_id IS NULL THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'You are not signed in.'
    );
  END IF;

  IF NOT api.has_app_role('ADMIN') THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'Admin role required.'
    );
  END IF;

  IF v_job_name = '' THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'job_name is required.'
    );
  END IF;

  IF v_interval IS NULL OR v_interval <= 0 THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'interval_seconds must be a positive integer.'
    );
  END IF;

  SELECT u.username
  INTO v_username
  FROM public."user" AS u
  WHERE u.user_id = v_user_id
    AND u.active IS NOT FALSE;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'Account not found.'
    );
  END IF;

  BEGIN
    IF v_stale_text IS NOT NULL THEN
      v_stale := v_stale_text::interval;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
      'ok', false,
      'message', 'stale_after_interval is not a valid interval.'
    );
  END;

  PERFORM api.set_audit_actor(v_username);

  UPDATE maintenance.job_definition AS d
  SET
    schedule_cron = NULL,
    interval_seconds = v_interval,
    stale_after_interval = COALESCE(v_stale, d.stale_after_interval),
    modified_date = CURRENT_TIMESTAMP,
    modified_by = v_username
  WHERE d.job_name = v_job_name;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'ok', false,
      'message', format('Unknown job_name: %s', v_job_name)
    );
  END IF;

  RETURN json_build_object(
    'ok', true,
    'job_name', v_job_name,
    'schedule_cron', NULL,
    'interval_seconds', v_interval,
    'message', format('Schedule for %s updated.', v_job_name)
  );
END;
$$;

REVOKE ALL ON FUNCTION api.set_scheduled_task_interval(text, integer, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION api.set_scheduled_task_interval(text, integer, text) TO authenticated;

NOTIFY pgrst, 'reload schema';$sqlbody$,
  $sort$131_set_scheduled_task_interval.sql$sort$,
  'c-agent'
);

INSERT INTO maintenance.schema_migration_catalog (
  filename, script_number, details, probe, sql_body, sort_key, created_by
) VALUES (
  $fn$132_session_status_cron_only_inactivity.sql$fn$,
  $num$132$num$,
  $details$session_status still uses activity_expires_at.$details$,
  $probe$EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'api' AND p.proname = 'session_status' AND position('activity_expires_at' in p.prosrc) = 0 AND position('user_session_is_active' in p.prosrc) > 0)$probe$,
  $sqlbody$-- session_status: treat a session as inactive only when the inactivity_logout
-- cron has stamped inactive_logout_at (user_session_is_active). Do not treat
-- stale last-activity as inactive without the scheduler.
-- Drop activity_expires_at (was only for the removed client local timer).
-- Run: psql -U postgres -d event_system_pro -f database/migrations/132_session_status_cron_only_inactivity.sql


CREATE OR REPLACE FUNCTION api.session_status()
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, api
AS $$
DECLARE
  v_user_id bigint;
  v_info json;
BEGIN
  v_user_id := api.current_user_id();

  IF v_user_id IS NULL THEN
    RETURN json_build_object(
      'ok', false,
      'active', false,
      'message', 'You are not signed in.'
    );
  END IF;

  SELECT u.additional_info_json
  INTO v_info
  FROM public."user" u
  WHERE u.user_id = v_user_id
    AND u.active IS NOT FALSE;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'ok', false,
      'active', false,
      'message', 'Account not found.'
    );
  END IF;

  IF NOT api.user_session_is_active(v_info) THEN
    RETURN json_build_object(
      'ok', true,
      'active', false,
      'message', 'You have been signed out due to inactivity to protect your account.',
      'last-activity', v_info::jsonb -> 'last-activity'
    );
  END IF;

  RETURN json_build_object(
    'ok', true,
    'active', true,
    'last-activity', v_info::jsonb -> 'last-activity'
  );
END;
$$;

